<?php
require_once __DIR__.'/backend/authorization.php';require_once __DIR__.'/backend/db.php';require_once __DIR__.'/backend/csrf.php';requireRegularAdmin();
$customers=$conn->query("SELECT id,full_name,email,phone_number FROM users WHERE role='user' AND account_status='active' ORDER BY full_name");
$services=$conn->query("SELECT id,service_name,category,description,price,duration_minutes,booking_availability,unavailable_reason FROM services WHERE status='active' ORDER BY category,display_order,service_name");
$days=(int)getSetting($conn,'booking_days_ahead','90');
