<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Booking | Oh My Gracious</title><link rel="stylesheet" href="css/style.css"></head><body>
<header class="navbar"><div class="logo">Front Desk</div><nav><a href="admin-dashboard.php">Dashboard</a><a href="admin-bookings.php">Appointments</a><a class="active" href="admin-create-booking.php">Create Booking</a><a href="availability-management.php">Availability</a><a href="customers.php">Customers</a><a href="logout.php" class="logout-btn">Logout</a></nav></header>
<main class="page-wrap narrow"><div class="page-heading"><div><p class="eyebrow">FRONT DESK BOOKING</p><h1>Create Appointment</h1><p>Create an appointment for an existing customer or a guest/walk-in without forcing account registration.</p></div></div>
<?php if(!empty($_GET['error'])):?><div class="alert error"><?=h((string)$_GET['error'])?></div><?php endif;?>
<form id="adminBookingForm" action="backend/admin-create-booking.php" method="POST" class="panel stack-lg"><?=csrfInput()?>
<section><h2>1. Customer</h2><div class="form-grid two"><div class="field span-2"><label>Booking Type</label><select id="customerMode" name="customer_mode"><option value="existing">Existing Customer Account</option><option value="guest">Guest / Walk-in</option></select></div><div id="existingCustomerFields" class="field span-2"><label>Customer Account</label><select name="user_id" id="existingCustomer"><option value="">Select customer</option><?php while($c=$customers->fetch_assoc()):?><option value="<?= (int)$c['id']?>"><?=h($c['full_name'].' — '.($c['phone_number']?:$c['email']))?></option><?php endwhile;?></select></div><div id="guestFields" class="form-grid two span-2 hidden"><div class="field"><label>Guest Name *</label><input name="guest_name" id="guestName"></div><div class="field"><label>Contact Number *</label><input name="guest_phone" id="guestPhone" placeholder="09XXXXXXXXX"></div><div class="field span-2"><label>Email (optional)</label><input name="guest_email" type="email"></div></div></div></section>
<section><h2>2. Services</h2><div class="service-grid"><?php $last=null; while($s=$services->fetch_assoc()): $available=$s['booking_availability']==='available'; if($last!==$s['category']):$last=$s['category'];?><div class="service-category-label"><?=h($last?:'General')?></div><?php endif;?><label class="service-option <?=$available?'':'unavailable'?>"><input class="service-check" type="checkbox" name="service_ids[]" value="<?= (int)$s['id']?>" data-price="<?=h($s['price'])?>" data-duration="<?= (int)$s['duration_minutes']?>" <?=$available?'':'disabled'?>><span><strong><?=h($s['service_name'])?></strong><small><?=h($s['description'])?></small><b>₱<?=number_format((float)$s['price'],2)?><?= (int)$s['duration_minutes']>0?' · ~'.(int)$s['duration_minutes'].' min':''?></b><?php if(!$available):?><em>Unavailable<?= $s['unavailable_reason']?' — '.h($s['unavailable_reason']):''?></em><?php endif;?></span></label><?php endwhile;?></div><div class="booking-summary"><div><span>Estimated service time</span><strong id="durationText">0 min</strong><small>Informational only.</small></div><div><span>Total</span><strong id="totalText">₱0.00</strong></div></div></section>
<section><h2>3. Date & Time</h2><div class="form-grid two"><div class="field"><label>Date</label><input id="bookingDate" name="booking_date" type="date" min="<?=date('Y-m-d')?>" max="<?=date('Y-m-d',strtotime('+'.$days.' days'))?>" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Available Time</label><select id="bookingTime" name="booking_time" required><option value="">Choose services first</option></select></div></div></section>
<section><h2>4. Notes & Payment</h2><div class="form-grid two"><div class="field"><label>Payment Method</label><input value="Pay at Salon (Cash)" readonly><input type="hidden" name="payment_method" value="Cash"><small>Online payment is not enabled in this release.</small></div><div class="field"><label>Payment Status</label><input value="To Pay" readonly></div><div class="field span-2"><label>Notes</label><textarea name="notes" rows="3"></textarea></div></div></section>
<button class="btn primary full">Create & Approve Appointment</button></form></main>
<script>
const checks=[...document.querySelectorAll('.service-check')],d=document.getElementById('bookingDate'),t=document.getElementById('bookingTime'),mode=document.getElementById('customerMode');
function ids(){return checks.filter(x=>x.checked).map(x=>x.value)}
function update(){let total=0,dur=0;checks.forEach(x=>{if(x.checked){total+=+x.dataset.price;dur+=+x.dataset.duration}});document.getElementById('totalText').textContent='₱'+total.toFixed(2);document.getElementById('durationText').textContent=dur?'~'+dur+' min':'Varies';load()}
async function load(){const x=ids();if(!x.length){t.innerHTML='<option value="">Choose services first</option>';return}const r=await fetch('backend/available-times.php?date='+encodeURIComponent(d.value)+'&service_ids='+x.join(','));const j=await r.json();t.innerHTML='<option value="">Select time</option>';if(j.status==='success')j.times.forEach(a=>{const o=new Option(a.label,a.value);o.disabled=!a.available;t.append(o)});else t.innerHTML='<option value="">'+(j.message||'Unavailable')+'</option>'}
function customerMode(){const guest=mode.value==='guest';document.getElementById('guestFields').classList.toggle('hidden',!guest);document.getElementById('existingCustomerFields').classList.toggle('hidden',guest);document.getElementById('existingCustomer').required=!guest;document.getElementById('guestName').required=guest;document.getElementById('guestPhone').required=guest;}
checks.forEach(x=>x.onchange=update);d.onchange=load;mode.onchange=customerMode;customerMode();update();
</script></body></html>
